define(["jquery"],function($){function showViolationMessage(){let message=$("#proctoringpolicy_focus-message");if(!message.length||!$.trim(message.html())){return}message.show()}function init(ctx,cfg){if(!ctx||!cfg||!cfg.enabled){return}let limit=parseInt(cfg.limit||0,10);if(isNaN(limit)||limit<0){limit=3}let count=0;let namespace=".kopere_proctoring_focus";function registerEvent(kind,detail){count++;showViolationMessage();if(typeof ctx.sendEvent==="function"){ctx.sendEvent("focus_"+kind,{count:count,detail:detail||""})}if(limit>0&&count>limit&&typeof ctx.lock==="function"){let message=$("#proctoringpolicy_focus-message").html();ctx.lock("focus",message||"")}}$(window).on("blur"+namespace,function(){registerEvent("blur","window")});$(document).on("visibilitychange"+namespace,function(){if(document.hidden){registerEvent("visibilitychange","hidden")}})}return{init:init}});